  "inlineSchema": "datasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// ==========================================\n// DIRECTORIO MAESTRO DE CATÁLOGOS\n// ==========================================\n\nmodel Catalogo {\n  id            Int     @id @default(autoincrement())\n  nombreTabla   String  @unique\n  tituloVisible String\n  orden         Int     @default(0)\n  activo        Boolean @default(true)\n\n  @@map(\"catalogo\")\n}\n\n// ==========================================\n// TABLAS DE CATÁLOGOS INSTITUCIONALES (Independientes para Admin)\n// ==========================================\n\nmodel TipoSecundaria {\n  id     Int    @id @default(autoincrement())\n  nombre String @unique\n\n  @@map(\"tipo_secundaria\")\n}\n\nmodel Subsistema {\n  id     Int    @id @default(autoincrement())\n  nombre String @unique\n\n  @@map(\"subsistema\")\n}\n\nmodel MedioEnterado {\n  id     Int    @id @default(autoincrement())\n  nombre String @unique\n\n  @@map(\"medio_enterado\")\n}\n\nmodel Genero {\n  id     Int    @id @default(autoincrement())\n  nombre String @unique\n\n  @@map(\"genero\")\n}\n\nmodel IdentidadCultural {\n  id     Int    @id @default(autoincrement())\n  nombre String @unique\n\n  @@map(\"identidad_cultural\")\n}\n\nmodel SituacionLaboral {\n  id     Int    @id @default(autoincrement())\n  nombre String @unique\n\n  @@map(\"situacion_laboral\")\n}\n\nmodel Discapacidad {\n  id     Int    @id @default(autoincrement())\n  nombre String @unique\n\n  @@map(\"discapacidad\")\n}\n\nmodel Parentesco {\n  id     Int    @id @default(autoincrement())\n  nombre String @unique\n\n  @@map(\"parentesco\")\n}\n\nmodel TipoEstudiante {\n  id     Int    @id @default(autoincrement())\n  nombre String @unique\n\n  @@map(\"tipo_estudiante\")\n}\n\nmodel Semestre {\n  id     Int    @id @default(autoincrement())\n  nombre String @unique\n\n  @@map(\"semestre\")\n}\n\n// ==========================================\n// MODELO PRINCIPAL DE ASPIRANTES (Guarda textos)\n// ==========================================\n\nmodel Aspirante {\n  id            Int       @id @default(autoincrement())\n  folio         String    @unique\n  vigenciaFolio DateTime?\n\n  // Datos Personales y de Contacto\n  apellidoPaterno    String\n  apellidoMaterno    String?\n  nombres            String\n  curp               String  @unique\n  correoElectronico1 String  @unique\n  correoElectronico2 String?\n  telefonoCelular    String\n  telefonoParticular String?\n\n  // Inclusión y Diversidad (Textos directos)\n  generoIdentidad   String?\n  identidadCultural String?\n  tieneDiscapacidad String?\n  apoyoEducativo    String? // Binario (SÍ / NO)\n\n  // Domicilio (SEPOMEX)\n  pais           String  @default(\"MÉXICO\")\n  codigoPostal   String\n  estado         String\n  municipio      String\n  colonia        String\n  calle          String\n  numeroExterior String?\n  numeroInterior String?\n\n  // Datos del Tutor\n  tutorApellidoPaterno String?\n  tutorApellidoMaterno String?\n  tutorNombres         String?\n  tutorParentesco      String?\n  tutorTelefono        String?\n\n  // Modalidad y Antecedentes Académicos\n  tipoAdmision             String // nuevo_ingreso o revalidacion\n  tipoSecundaria           String?\n  cctEscuelaProcedencia    String?\n  nombreEscuelaProcedencia String?\n  estadoEscuelaProcedencia String?\n  promedioSecundaria       String?\n\n  // Historial de Bachillerato (Revalidación)\n  sistemaBachilleratoPrevio String?\n  otroSistemaProcedencia    String?\n  cctBachilleratoPrevio     String?\n  nombreBachilleratoPrevio  String?\n  estadoBachilleratoPrevio  String?\n  tipoEstudiante            String?\n  semestreActual            String?\n  planEstudios              String?\n\n  // Perfil Tecnológico y Estadística\n  situacionLaboral  String?\n  cuentaComputadora String? // Binario (SÍ / NO)\n  cuentaInternet    String? // Binario (SÍ / NO)\n  medioEnterado     String?\n\n  // Fechas del Sistema\n  creadoEn      DateTime @default(now())\n  actualizadoEn DateTime @updatedAt\n\n  // Relación con Expediente Digital\n  documentos Documento[]\n\n  @@map(\"aspirante\")\n}\n\n// ==========================================\n// MODELO DE DOCUMENTOS (Expediente Digital)\n// ==========================================\n\nmodel Documento {\n  id            Int       @id @default(autoincrement())\n  aspiranteId   Int\n  aspirante     Aspirante @relation(fields: [aspiranteId], references: [id], onDelete: Cascade)\n  tipoDoc       String\n  nombreArchivo String\n  archivoBlob   Bytes // Almacena el archivo binario directamente en la BD\n  estatusDoc    String    @default(\"EN REVISIÓN\")\n  creadoEn      DateTime  @default(now())\n\n  @@map(\"documento\")\n}\n",
